<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {brewApi} from '../api';
const catalog=ref({items:[],factories:[],scope_label:''}),code=ref(''),factory=ref(''),keyword=ref(''),from=ref(''),to=ref(''),result=ref(null),loading=ref(false),error=ref(''),page=ref(1),pageSize=ref(20),applied=ref({}),scope=ref('');
let sequence=0;
const groups=computed(()=>[...new Set(catalog.value.items.map(r=>r.group))]);
const definition=computed(()=>catalog.value.items.find(r=>r.code===code.value));
const query=()=>({factory_id:factory.value,keyword:keyword.value,...(definition.value?.dated?{date_from:from.value,date_to:to.value}:{})});
const download=computed(()=>result.value?brewApi.reportDownloadUrl(result.value.definition.code,applied.value):'');
const display=(row,col)=>{const v=row[col.key];if(v===null||v===undefined||v==='')return '—';if(['at','completed_at','expires'].includes(col.key))return new Date(/[zZ]|[+-]\d\d:\d\d$/.test(v)?v:v+'Z').toLocaleString('zh-CN',{timeZone:catalog.value.timezone||'Asia/Shanghai',hour12:false});return typeof v==='number'?v.toLocaleString('zh-CN',{maximumFractionDigits:3}):v;};
async function load(reset=true){if(!code.value)return;if(reset){page.value=1;applied.value=query();scope.value=catalog.value.factories.find(f=>f.id===factory.value)?.name||catalog.value.scope_label;}const id=++sequence;loading.value=true;error.value='';try{const data=await brewApi.getReportData(code.value,{...applied.value,page:page.value,page_size:pageSize.value});if(id===sequence)result.value=data;}catch(e){if(id===sequence){error.value=e.message;result.value=null;}}finally{if(id===sequence)loading.value=false;}}
async function choose(value){code.value=value;result.value=null;await load();}
onMounted(async()=>{try{catalog.value=await brewApi.getReportCatalog();const now=new Date();to.value=now.toLocaleDateString('sv-SE',{timeZone:catalog.value.timezone||'Asia/Shanghai'});from.value=to.value.slice(0,8)+'01';if(catalog.value.factories.length===1)factory.value=catalog.value.factories[0].id;code.value=catalog.value.items[0]?.code||'';await load();}catch(e){error.value=e.message;}});
onUnmounted(()=>{sequence++;});
</script>
<template>
  <section class="reports-workspace">
    <header class="reports-title"><h2>报表导出</h2><span>{{ catalog.scope_kind === 'headquarters' ? '总部报表' : '酒厂报表' }} · {{ catalog.factories.length }} 个酒厂</span></header>
    <div v-if="error" class="master-error" role="alert">{{ error }}</div>
    <div class="reports-layout">
      <aside class="reports-nav" aria-label="选择报表"><section v-for="group in groups" :key="group"><h3>{{ group }}</h3><button v-for="r in catalog.items.filter(r => r.group === group)" :key="r.code" type="button" :class="{active:code === r.code}" :aria-pressed="code === r.code" @click="choose(r.code)">{{ r.name }}<span>›</span></button></section></aside>
      <main class="reports-main">
        <template v-if="definition">
          <header class="reports-heading">
            <h3 :title="definition.description">{{ definition.name }}</h3>
            <form class="reports-filters" @submit.prevent="load()">
              <select v-if="catalog.factories.length > 1" v-model="factory" class="reports-factory" aria-label="报表酒厂"><option value="">全部授权酒厂</option><option v-for="f in catalog.factories" :value="f.id" :key="f.id">{{ f.name }}</option></select>
              <div v-if="definition.dated" class="reports-date-range" role="group" aria-label="报表日期范围"><input v-model="from" aria-label="开始日期" type="date" required><span>—</span><input v-model="to" aria-label="结束日期" type="date" :min="from" required></div>
              <input class="reports-keyword" v-model.trim="keyword" aria-label="报表关键词" type="search" placeholder="酒品 / 批次 / 单号">
              <button class="btn btn-sm btn-outline" type="submit" :disabled="loading">{{ loading ? '查询中…' : '查询' }}</button>
              <a v-if="result && !loading" class="btn btn-sm btn-primary reports-export" :href="download" title="导出当前查询的全部结果，可用 Excel 打开">导出 CSV <span aria-hidden="true">↓</span></a>
            </form>
          </header>
          <div v-if="result" class="reports-result-caption"><span>{{ scope }}<template v-if="!definition.dated"> · 当前快照</template><template v-else> · {{ applied.date_from }} 至 {{ applied.date_to }}</template></span><span>{{ result.total }} 条记录</span></div>
          <div class="reports-table-wrap" :aria-busy="loading" role="region" :aria-label="definition.name + '数据表'" tabindex="0">
            <table v-if="result" class="reports-sheet">
              <thead><tr><th class="reports-row-index" scope="col">#</th><th v-for="col in result.definition.columns" :key="col.key" scope="col" :class="{'reports-numeric': result.rows.some(row => typeof row[col.key] === 'number')}">{{ col.label }}</th></tr></thead>
              <tbody><tr v-for="(row,index) in result.rows" :key="row.id || index"><th class="reports-row-index" scope="row">{{ ((result.page || page) - 1) * pageSize + index + 1 }}</th><td v-for="col in result.definition.columns" :key="col.key" :class="{'reports-numeric': typeof row[col.key] === 'number'}" :title="display(row,col)">{{ display(row,col) }}</td></tr></tbody>
            </table>
            <div v-if="!result?.rows.length" class="reports-empty" role="status"><span>{{ loading ? '正在查询…' : '当前条件下暂无记录' }}</span><small v-if="!loading">可调整日期、酒厂或关键词后查询</small></div>
          </div>
          <footer class="reports-pagination" aria-label="报表分页">
            <span>{{ result?.total ? ((page - 1) * pageSize + 1) + '–' + Math.min(page * pageSize,result.total) : 0 }} / 共 {{ result?.total || 0 }} 条</span>
            <div><select v-model.number="pageSize" aria-label="每页记录数" :disabled="loading" @change="load()"><option :value="20">20 条 / 页</option><option :value="50">50 条 / 页</option><option :value="100">100 条 / 页</option></select><button type="button" :disabled="page <= 1 || loading" @click="page--;load(false)">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil((result?.total || 0) / pageSize)) }}</span><button type="button" :disabled="!result || page * pageSize >= result.total || loading" @click="page++;load(false)">下一页</button></div>
          </footer>
        </template>
        <div v-else class="reports-empty">当前角色暂无可用报表</div>
      </main>
    </div>
  </section>
</template>
<style scoped>
.reports-workspace{height:calc(100dvh - 64px);min-height:480px;display:flex;flex-direction:column}.reports-title{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 20px;flex-shrink:0}.reports-title h2{font-size:21px;margin:0}.reports-title>span{font-size:11px;color:var(--text-muted)}.reports-layout{display:grid;grid-template-columns:155px minmax(0,1fr);gap:20px;flex:1;min-height:0}.reports-nav{overflow:auto;min-height:0;padding-right:3px}.reports-nav h3{font-size:10px;font-weight:400;color:var(--text-muted);margin:0 0 8px;padding:0 10px}.reports-nav section{margin-bottom:22px}.reports-nav button{display:flex;width:100%;justify-content:space-between;padding:10px;margin-bottom:2px;border:0;border-radius:6px;background:none;color:var(--text-secondary);font:inherit;font-size:12px;text-align:left;cursor:pointer}.reports-nav button:hover{background:#ffffff04}.reports-nav button span{opacity:.35}.reports-nav button.active{background:#d4aa4e14;color:var(--accent-gold)}.reports-main{display:flex;flex-direction:column;border:1px solid var(--border-default);border-radius:10px;min-width:0;min-height:0;overflow:hidden;background:var(--bg-surface)}.reports-heading{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;padding:16px 18px;border-bottom:1px solid var(--border-default);flex-shrink:0}.reports-heading h3{font-size:16px;margin:0;white-space:nowrap}.reports-filters{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap;margin-left:auto;min-width:0}.reports-filters :is(input,select,.btn){box-sizing:border-box;height:34px!important;min-height:34px!important;padding:0 9px!important;line-height:normal;font:inherit;font-size:11px!important;border-radius:6px;margin:0;min-width:0}.reports-filters :is(input,select){background:var(--bg-input);color:var(--text-primary);border:1px solid var(--border-default);color-scheme:dark}.reports-factory{width:125px}.reports-date-range{display:flex;align-item