ow-index{z-index:3}.reports-sheet .reports-numeric{text-align:right;font-variant-numeric:tabular-nums}.reports-empty{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;min-height:160px;height:calc(100% - 38px);padding:24px;box-sizing:border-box;color:var(--text-muted);font-size:13px}.reports-empty small{font-size:11px;opacity:.7}.reports-pagination{display:flex;align-items:center;justify-content:space-between;flex-shrink:0;gap:12px;padding:12px 18px;font-size:11px;color:var(--text-muted);margin-top:auto;background:var(--bg-surface)}.reports-pagination>div{display:flex;align-items:center;gap:12px}.reports-pagination select,.reports-pagination button{box-sizing:border-box;min-height:30px;padding:0 9px;border:1px solid var(--border-default);background:var(--bg-input);color:var(--text-secondary);border-radius:5px;font:inherit}.reports-pagination button{cursor:pointer}.reports-pagination button:disabled{opacity:.35;cursor:default}.reports-workspace :is(button,input,select,a):focus-visible{outline:2px solid var(--accent-gold);outline-offset:2px}@media(max-width:1250px){.reports-layout{grid-template-columns:145px minmax(0,1fr);gap:12px}.reports-filters{justify-content:flex-start}.reports-keyword{width:145px}}@media(max-width:900px){.reports-layout{grid-template-columns:1fr;grid-template-rows:auto minmax(0,1fr)}.reports-nav{display:flex;gap:12px;overflow:auto;min-height:40px}.reports-nav section{display:flex;flex:none;gap:4px;margin:0 0 6px}.reports-nav h3,.reports-nav button span{display:none}.reports-nav button{width:auto;white-space:nowrap}.reports-heading{padding:14px 12px}.reports-result-caption{padding:10px 12px}.reports-pagination{padding:10px 12px}}@media(max-width:600px){.reports-workspace{min-height:600px}.reports-filters{width:100%;margin-left:0}.reports-keyword{flex:1;min-width:120px}.reports-date-range input{width:113px}.reports-title>span{display:none}.reports-pagination{flex-wrap:wrap}.reports-pagination>div{gap:9px;margin-le